    );
end package oled_font_pkg;

package body oled_font_pkg is
    function ch(c : character) return t_char is
    begin
        for i in FONT_CHARS'range loop
            if FONT_CHARS(i) = c then return i - FONT_CHARS'low; end if;
        end loop;
        return ch(' ');
    end function;
end package body oled_font_pkg;
